/**
 * Regenerates the package manifests that live outside this repository from the
 * assets of a published GitHub release:
 *
 *   packaging/homebrew/Casks/storyforge.rb   → LovelessCodes/homebrew-tap
 *   packaging/scoop/bucket/storyforge.json   → LovelessCodes/scoop-bucket
 *   packaging/aur/PKGBUILD + .SRCINFO        → AUR storyforge-bin
 *
 * `.github/workflows/distribute.yml` runs this on `release: published` and
 * copies the files into those repositories, so none of them are edited by hand
 * — editing a generated file only makes it drift until the next release.
 *
 *   bun scripts/packaging/update-manifests.ts                     # package.json version
 *   bun scripts/packaging/update-manifests.ts --tag storyforge-v2.0.11
 *   bun scripts/packaging/update-manifests.ts --only homebrew,aur   # skip a channel
 *   bun scripts/packaging/update-manifests.ts --check                # offline drift check
 *   bun scripts/packaging/update-manifests.ts --version-only --version 2.0.12
 *
 * `--check` needs no network: it only asserts that each manifest still carries
 * the version from package.json, which is what a hand-cut release forgets.
 *
 * `--version-only` moves just the version strings and is what
 * `scripts/bump-version.ts` calls for the upcoming release — checksums can only
 * be right once the artifacts exist, so they are left for the release run.
 *
 * The Scoop manifest prefers the portable Windows zip that `publish.yml` builds,
 * and falls back to unpacking the NSIS installer for older releases.
 */

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const ROOT = join(import.meta.dirname, "../..");
const REPO = "LovelessCodes/StoryForge";
const HOMEPAGE = "https://getstoryforge.app/";
const MAINTAINER = "Mike Kold Hermann <mkh@cleanmanager.dk>";
const GENERATED = "Generated by scripts/packaging/update-manifests.ts — do not edit by hand.";

const CASK_PATH = "packaging/homebrew/Casks/storyforge.rb";
const SCOOP_PATH = "packaging/scoop/bucket/storyforge.json";
const PKGBUILD_PATH = "packaging/aur/PKGBUILD";
const SRCINFO_PATH = "packaging/aur/.SRCINFO";

const pkg = JSON.parse(readFileSync(join(ROOT, "package.json"), "utf-8")) as { version: string };

const ARGV = process.argv.slice(2);
const CHECK = ARGV.includes("--check");

const onlyIndex = ARGV.indexOf("--only");
const only =
  onlyIndex >= 0 && ARGV[onlyIndex + 1]
    ? new Set(ARGV[onlyIndex + 1].split(",").map((c) => c.trim()))
    : null;
const wants = (channel: string) => only === null || only.has(channel);

// ── helpers ──

function read(path: string) {
  return readFileSync(join(ROOT, path), "utf-8");
}

function write(path: string, contents: string) {
  const full = join(ROOT, path);
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, contents);
  console.log(`  ${path}`);
}

function assetUrl(tag: string, name: string) {
  return `https://github.com/${REPO}/releases/download/${tag}/${name}`;
}

async function sha256(url: string) {
  const res = await fetch(url, { redirect: "follow" });
  if (!res.ok) {
    throw new Error(`cannot download ${url}: ${res.status} ${res.statusText}`);
  }
  const body = new Uint8Array(await res.arrayBuffer());
  return createHash("sha256").update(body).digest("hex");
}

// ── templates ──

function cask(version: string, armHash: string, intelHash: string) {
  return `# ${GENERATED}
cask "storyforge" do
  version "${version}"
  sha256 arm:   "${armHash}",
         intel: "${intelHash}"

  on_arm do
    url "https://github.com/${REPO}/releases/download/storyforge-v#{version}/Story.Forge_#{version}_aarch64.dmg"
  end
  on_intel do
    url "https://github.com/${REPO}/releases/download/storyforge-v#{version}/Story.Forge_#{version}_x64.dmg"
  end

  name "Story Forge"
  desc "Launcher and mod manager for Vintage Story"
  homepage "${HOMEPAGE}"

  # The app updates itself through the Tauri updater, so Homebrew must not also
  # report its own (older) copy as an upgrade.
  auto_updates true
  depends_on :macos

  app "Story Forge.app"

  # Profiles, downloaded game versions and worlds live in
  # ~/Library/Application Support/StoryForge and are deliberately left out of
  # \`zap\`: uninstalling the app must not delete the user's game data.
  zap trash: [
    "~/Library/Caches/StoryForge",
    "~/Library/Preferences/StoryForge.plist",
    "~/Library/Saved Application State/StoryForge.savedState",
  ]
end
`;
}

function scoop(version: string, source: { name: string; hash: string; extract: boolean }) {
  const url = assetUrl(`storyforge-v${version}`, source.name);
  const download = source.extract ? `${url}#/dl.7z` : url;

  const manifest: Record<string, unknown> = {
    $schema: "https://raw.githubusercontent.com/ScoopInstaller/Scoop/master/schema.json",
    version,
    description: "A modern desktop launcher and mod manager for Vintage Story",
    homepage: HOMEPAGE,
    license: "GPL-3.0-only",
    architecture: { "64bit": { url: download, hash: source.hash } },
  };

  if (source.extract) {
    // Tauri's NSIS installer is a 7-Zip-readable archive: `#/dl.7z` makes Scoop
    // unpack it and drop the `$PLUGINSDIR` / `$TEMP` helpers afterwards. Used
    // for releases that predate the portable zip.
    manifest["##"] =
      "Scoop unpacks the NSIS installer; post_install drops the installer helpers. Releases that ship Story.Forge_<version>_x64-portable.zip use that instead.";
    manifest.post_install =
      'Remove-Item "$dir\\`$*", "$dir\\Uninstall*" -Force -Recurse -ErrorAction SilentlyContinue';
    manifest.shortcuts = [["StoryForge.exe", "Story Forge"]];
  } else {
    manifest.shortcuts = [["Story Forge.exe", "Story Forge"]];
  }

  // The tag carries a `storyforge-v` prefix, so pull the version out of it.
  manifest.checkver = {
    github: `https://github.com/${REPO}`,
    regex: "storyforge-v([\\d.]+)",
  };
  manifest.autoupdate = {
    architecture: {
      "64bit": {
        url: `https://github.com/${REPO}/releases/download/storyforge-v$version/${source.extract ? "Story.Forge_$version_x64-setup.exe#/dl.7z" : "Story.Forge_$version_x64-portable.zip"}`,
      },
    },
  };

  return `${JSON.stringify(manifest, null, 2)}\n`;
}

function pkgbuild(version: string, debHash: string) {
  return `# ${GENERATED}
# Maintainer: ${MAINTAINER}
pkgname=storyforge-bin
pkgver=${version}
pkgrel=1
pkgdesc='A modern desktop launcher and mod manager for Vintage Story'
arch=('x86_64')
url='https://github.com/${REPO}'
license=('GPL-3.0-only')
depends=('gtk3' 'webkit2gtk-4.1' 'libayatana-appindicator' 'hicolor-icon-theme')
provides=('storyforge')
conflicts=('storyforge')
options=('!strip')

# Repackages the Tauri .deb so the AUR tracks the release artifact rather than
# rebuilding the app. Version and checksum come from the release, see
# packaging/aur/README.md.
_debname="Story.Forge_\${pkgver}_amd64.deb"
source=("\${_debname}::https://github.com/${REPO}/releases/download/storyforge-v\${pkgver}/\${_debname}")
sha256sums=('${debHash}')

build() {
  cd "\${srcdir}"
  bsdtar -xf "\${_debname}"
}

package() {
  cd "\${srcdir}"
  tar -xzf data.tar.gz -C "\${pkgdir}"
}
`;
}

function srcinfo(version: string, debHash: string) {
  return `pkgbase = storyforge-bin
	pkgdesc = A modern desktop launcher and mod manager for Vintage Story
	pkgver = ${version}
	pkgrel = 1
	url = https://github.com/${REPO}
	arch = x86_64
	license = GPL-3.0-only
	depends = gtk3
	depends = webkit2gtk-4.1
	depends = libayatana-appindicator
	depends = hicolor-icon-theme
	provides = storyforge
	conflicts = storyforge
	options = !strip
	source = Story.Forge_${version}_amd64.deb::https://github.com/${REPO}/releases/download/storyforge-v${version}/Story.Forge_${version}_amd64.deb
	sha256sums = ${debHash}

pkgname = storyforge-bin
`;
}

// ── check mode ──

const MANIFESTS: { path: string; re: RegExp }[] = [
  { path: CASK_PATH, re: /^\s*version "([^"]+)"/m },
  { path: SCOOP_PATH, re: /^\s*"version": "([^"]+)"/m },
  { path: PKGBUILD_PATH, re: /^pkgver=(.+)$/m },
  { path: SRCINFO_PATH, re: /^\tpkgver = (.+)$/m },
];

if (CHECK) {
  // A pre-release is never packaged for a package manager: the tap, bucket and
  // AUR only ever point at a stable release, so package.json is allowed to run
  // ahead of them between an `rc` bump and the matching final release.
  if (pkg.version.includes("-")) {
    console.log(`package.json is at ${pkg.version}; manifests track the last stable release.`);
    process.exit(0);
  }

  const expected = pkg.version;
  const stale: string[] = [];
  for (const { path, re } of MANIFESTS) {
    if (!existsSync(join(ROOT, path))) {
      console.log(`  ${path}: not generated yet, skipped`);
      continue;
    }
    const found = read(path).match(re)?.[1]?.trim();
    if (found !== expected) {
      stale.push(`  ${path}: ${found ?? "<missing>"} (expected ${expected})`);
    }
  }

  if (stale.length > 0) {
    console.error(`Package manifests are out of sync with package.json (${expected}):`);
    console.error(stale.join("\n"));
    console.error("\nRun: bun scripts/packaging/update-manifests.ts");
    process.exit(1);
  }
  console.log(`Package manifests match package.json (${expected}).`);
  process.exit(0);
}

// ── version-only mode ──
//
// Called by scripts/bump-version.ts so the manifests name the version that is
// about to be released. The checksums still belong to the previous release and
// are only true again once the release workflow regenerates the manifests from
// the actual assets — nothing pushes these files directly, the distribute
// workflow always regenerates before it commits into the tap, bucket or AUR.

if (ARGV.includes("--version-only")) {
  const index = ARGV.indexOf("--version");
  const next = index >= 0 ? ARGV[index + 1] : pkg.version;

  if (!next || next.includes("-")) {
    console.log(`Not touching the manifests for ${next ?? "an unknown version"} (pre-release).`);
    process.exit(0);
  }

  for (const { path, re } of MANIFESTS) {
    if (!existsSync(join(ROOT, path))) continue;
    const contents = read(path);
    const current = contents.match(re)?.[1]?.trim();
    if (!current || current === next) continue;
    write(path, contents.split(current).join(next));
  }
  process.exit(0);
}

// ── regenerate ──

const tagIndex = ARGV.indexOf("--tag");
const tag = tagIndex >= 0 && ARGV[tagIndex + 1] ? ARGV[tagIndex + 1] : `storyforge-v${pkg.version}`;
const version = tag.replace(/^storyforge-v/, "");

if (!/^\d+\.\d+\.\d+$/.test(version)) {
  console.error(`Refusing to generate manifests for a non-release tag: ${tag}`);
  process.exit(1);
}

console.log(`Generating package manifests for ${tag}\n`);

// Each channel downloads its own artifact. A missing asset is a warning, not a
// failure: a backfill run for an older tag must still be able to refresh the
// channels whose artifacts do exist (the distribute workflow re-checks each
// manifest's version before pushing anything).

async function hashOf(url: string, channel: string) {
  return sha256(url).catch(() => {
    console.warn(`  skipping ${channel}: ${url} is missing`);
    return null;
  });
}

if (wants("homebrew")) {
  const [armHash, intelHash] = await Promise.all([
    hashOf(assetUrl(tag, `Story.Forge_${version}_aarch64.dmg`), "homebrew"),
    hashOf(assetUrl(tag, `Story.Forge_${version}_x64.dmg`), "homebrew"),
  ]);
  if (armHash && intelHash) write(CASK_PATH, cask(version, armHash, intelHash));
}

if (wants("aur")) {
  const debHash = await hashOf(assetUrl(tag, `Story.Forge_${version}_amd64.deb`), "aur");
  if (debHash) {
    write(PKGBUILD_PATH, pkgbuild(version, debHash));
    write(SRCINFO_PATH, srcinfo(version, debHash));
  }
}

if (wants("scoop")) {
  // Prefer the portable zip, but keep older releases installable: the NSIS
  // installer is a 7-Zip archive Scoop can unpack (that is how the bucket
  // shipped 2.0.0).
  const portable = `Story.Forge_${version}_x64-portable.zip`;
  const installer = `Story.Forge_${version}_x64-setup.exe`;

  const portableHash = await hashOf(assetUrl(tag, portable), "scoop portable zip");
  if (portableHash) {
    write(SCOOP_PATH, scoop(version, { name: portable, hash: portableHash, extract: false }));
  } else {
    const installerHash = await hashOf(assetUrl(tag, installer), "scoop installer");
    if (installerHash) {
      write(SCOOP_PATH, scoop(version, { name: installer, hash: installerHash, extract: true }));
    }
  }
}

console.log(`\nDone. ${version} is ready for the Homebrew tap, Scoop bucket and AUR.`);
